contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: parameters include a caller candidate and an amount to send to c
    function run(address payable possibleOwner, address payable recipient, uint128 deposit) public payable {
        require(address(this).balance >= deposit);

        // Note: c was deployed fresh by the harness with some owner address; we cannot redeploy it here.
        // We will read current owner, then try to withdraw as that owner (by making this contract the owner is impossible),
        // but we can still assert that when msg.sender equals owner the contract's balance moves to recipient.

        // Read owner before any action
        address ownerBefore = c.owner();

        // Deposit Ether into c by calling its fallback payable function
        // send deposit from this contract to c
        (bool sent,) = address(c).call{value: deposit}("");
        require(sent);

        // Record balances before attempting withdrawal
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        // Attempt withdrawAll as this contract (msg.sender = address(this)). Capture revert status.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read owner after call
        address ownerAfter = c.owner();

        // Read balances after
        uint256 cBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        // General rule: if this contract was the owner (i.e., msg.sender == ownerBefore), the call must not revert,
        // c's entire balance must have moved to recipient, and owner must remain unchanged.
        // Otherwise (not owner), the call must revert and balances unchanged and owner unchanged.
        assert(
            ownerAfter == ownerBefore && (
                (ownerBefore == address(this) && reverted == false && cBalanceBefore == 0 && recipientBalanceAfter == recipientBalanceBefore + cBalanceBefore) ||
                (ownerBefore != address(this) && reverted == true && cBalanceAfter == cBalanceBefore && recipientBalanceAfter == recipientBalanceBefore)
            )
        );
    }

    receive() external payable {}
}

