contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address maybeOwner, address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        // We expect the deployed C to have been constructed before this test run by the checker.
        // The test must consider two cases: when this contract is the owner (can call) or not.

        // read owner and balance before
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // fund C with some Ether to allow meaningful transfer
        if (amount > 0) {
            // send Ether to C
            (bool ok,) = address(c).call{value: amount}("");
            require(ok);
        }

        // record balance after funding
        uint balanceAfterFund = address(c).balance;

        // attempt withdraw and catch revert
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceFinal = address(c).balance;

        // General property:
        // - If the caller (this contract) equals ownerBefore, call must not revert and C's balance becomes zero
        //   and the final balance equals zero and is less-or-equal to before-fund (monotonic).
        // - If caller is not ownerBefore, call must revert and C's balance must be unchanged from before the withdraw attempt.

        if (address(this) == ownerBefore) {
            // when owner: withdraw should succeed and drain contract
            assert(reverted == false && balanceFinal == 0);
        } else {
            // when not owner: withdraw should have reverted and balance unchanged
            assert(reverted == true && balanceFinal == balanceAfterFund);
        }
    }

    receive() external payable {}
}

