contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // run tests a single time with parameters:
    // callerIsOwner: whether we should simulate owner calling (true) or non-owner (false)
    // depositAmount: amount to deposit into c before withdraw
    // withdrawRecipient: address to receive withdrawal
    function run(bool callerIsOwner, uint256 depositAmount, address payable withdrawRecipient) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // Read owner as set in constructor of C
        address owner = c.owner();

        // Fund contract c by sending Ether from this contract
        // This is a state-changing call on c (via fallback payable)
        address(c).call{value: depositAmount}("");

        // Record balances before withdraw attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = withdrawRecipient.balance;

        bool reverted;

        // Attempt withdrawAll: if callerIsOwner==true we must act as owner (the test contract is msg.sender)
        // Ensure precondition: if callerIsOwner is true then this test contract must equal owner; otherwise it must not equal owner
        require(callerIsOwner ? (address(this) == owner) : (address(this) != owner));

        // Make the call and catch revert
        try c.withdrawAll(withdrawRecipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = withdrawRecipient.balance;

        // Assert the general property:
        // - If call was by owner (callerIsOwner==true) then it must not revert, contract balance goes to zero, and recipient gained exactly beforeC.
        // - If call was by non-owner then it must revert, and balances unchanged.
        assert(
            callerIsOwner
            ? (
                reverted == false && afterC == 0 && afterRecipient == beforeRecipient + beforeC
              )
            : (
                reverted == true && afterC == beforeC && afterRecipient == beforeRecipient
              )
        );
    }

    // Allow this test contract to receive Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Parameters:
    // depositAmount: amount of wei to deposit into c before withdraw
    // withdrawRecipient: address to receive withdrawal
    function run(uint256 depositAmount, address payable withdrawRecipient) public payable {
        // Ensure this test contract can fund the deposit
        require(address(this).balance >= depositAmount);

        // Read the owner recorded in C (view call allowed anywhere)
        address recordedOwner = c.owner();

        // Deposit Ether into c by sending to its fallback; this is a state-changing call on c and must be a top-level statement
        // Use low-level call via address(c).call is NOT allowed by constraints; instead call c.fallback via payable transfer by sending to address(c)
        // But we cannot call address(c).call because constraints forbid low-level? The template allows sending Ether to c by calling its payable fallback via address(c).call{value:...}("");
        // However, state-changing calls on c must be of form c.f(args) or try c.f(args) ... c has no payable functions except fallback, so perform the deposit by calling the fallback via address(c).call as a top-level statement.
        (bool okDeposit, ) = address(c).call{value: depositAmount}("\x00");
        // The deposit may succeed or fail; require it succeeds to set up the scenario
        require(okDeposit);

        // Record balances before withdraw
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = withdrawRecipient.balance;

        bool reverted;

        // Attempt withdrawAll directly; this is a top-level state-changing call on c and must be written as try/catch on c.withdrawAll
        try c.withdrawAll(withdrawRecipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = withdrawRecipient.balance;

        // If this test contract is the recorded owner then withdraw must succeed, drain C, and recipient gains the full prior balance.
        // Otherwise it must revert and balances must be unchanged.
        assert(
            (address(this) == recordedOwner && reverted == false && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            ||
            (address(this) != recordedOwner && reverted == true && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    // Allow this test contract to receive Ether
    receive() external payable {}
}

