contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters to exercise withdrawAll
    function run(address ownerCandidate, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);

        // The contract C was deployed fresh by the checker; we cannot redeploy.
        // We simulate two scenarios in one function by observing behavior depending on who c.owner() is.

        // Fund C by sending Ether from this test to c
        if (fund > 0) {
            // send Ether to C using its fallback
            payable(address(c)).transfer(fund);
        }

        // Read pre-state
        uint256 beforeCBalance = address(c).balance;
        address currentOwner = c.owner();
        uint256 beforeThisBalance = address(this).balance;

        // Try withdrawAll as this contract (msg.sender will be this contract)
        bool reverted;
        try c.withdrawAll({ _recipient: recipient }) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterCBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // General rule asserted:
        // If this contract is not the owner, the call must revert and balances unchanged on c.
        // If this contract is the owner, the call must not revert and c's balance must become zero and
        // recipient receives the funds (we observe that c.balance decreased by beforeCBalance).
        // Because recipient may be an external address we cannot inspect its balance, but we can assert c's balance change.
        assert(
            // Case A: not owner => reverted and c.balance unchanged
            ((currentOwner != address(this)) && reverted && afterCBalance == beforeCBalance)
            ||
            // Case B: owner => not reverted and c.balance becomes zero and decreased by exactly beforeCBalance
            ((currentOwner == address(this)) && !reverted && afterCBalance == 0 && beforeCBalance == beforeCBalance)
        );
    }

    // Allow receiving Ether so this contract can fund C
    receive() external payable {}
}

