contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // msg.sender for calls into c will be this contract
    // parameters: who calls withdraw (as the _sender simulation via try/catch), recipient, and an amount to fund c
    function run(address caller, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund, "insufficient balance to fund c");

        // Fund contract c by sending Ether to it from this contract
        // Note: C has a payable fallback(), so use transfer via address(c).call{value: fund}()
        (bool okFund, ) = address(c).call{value: fund}("\x00");
        require(okFund, "funding failed");

        // Read owner and balances before the withdraw attempt
        address ownerBefore = c.owner();
        uint256 balanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        // Try to have 'caller' invoke withdrawAll on c. Because calls originate from this contract,
        // we simulate caller by using c.withdrawAll when caller == address(this) (allowed),
        // otherwise we perform a low-level call with from=caller is impossible here, so instead
        // we check the two cases: if caller==address(this) then this contract is the msg.sender; otherwise
        // any call from this contract will not be from 'caller' and should revert when caller != owner.

        bool reverted;
        if (caller == address(this)) {
            // This contract will call withdrawAll and will succeed iff ownerBefore == address(this)
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // We cannot make c see msg.sender == caller when caller != address(this), so any call we make
            // will come from this contract and thus should behave as caller = address(this).
            // To exercise the intended property, we still attempt the call and record if it reverts.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read balances after the attempt
        uint256 balanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        // General rule: withdrawAll transfers the full contract balance to _recipient iff msg.sender == owner.
        // In our environment msg.sender for the call is address(this). So: if address(this) == ownerBefore then the call must not revert
        // and the contract's entire balance must move to recipient; otherwise the call must revert and balances unchanged.
        assert(
            (
                address(this) == ownerBefore
                && reverted == false
                && balanceBefore == balanceAfter + (recipientBalanceAfter - recipientBalanceBefore)
                && balanceAfter == 0
            )
            ||
            (
                address(this) != ownerBefore
                && reverted == true
                && balanceBefore == balanceAfter
                && recipientBalanceBefore == recipientBalanceAfter
            )
        );
    }

    receive() external payable {}
}

