contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params: caller address candidate, recipient, and an amount to fund c
    function run(address caller, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);

        // Fund contract c by sending Ether to it from this test contract
        // Use low-level call via the fallback: send Ether to c
        (bool sent, ) = address(c).call{value: fund}("");
        require(sent);

        // read pre-state
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        address owner = c.owner();

        // decide who will invoke withdrawAll: we must simulate calls from either owner or non-owner
        bool reverted;
        if (caller == address(this)) {
            // Call as this contract (which is the deployer of c), so msg.sender == this
            // Perform directly and catch revert
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // To make the call originate from an arbitrary caller, deploy a minimal forwarder inline.
            // We declare a local contract type via assembly by creating a contract on the fly.
            // Since we cannot declare new contracts here, use a simple technique: call withdrawAll via a proxy contract created now.
            Forwarder f = new Forwarder();
            // Fund the forwarder so it can call (not strictly necessary for non-payable call)
            (bool s2, ) = address(f).call{value: 0}("");
            require(s2 || true);
            try f.callWithdraw(address(c), recipient, caller) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // - If caller equals owner then the call must not revert and afterC == 0 and recipient gained exactly beforeC.
        // - If caller != owner then the call must revert and balances unchanged.
        assert(
            (caller == owner && !reverted && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            || (caller != owner && reverted && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    receive() external payable {}
}

// Minimal forwarder contract to enable calls from arbitrary caller addresses
contract Forwarder {
    // allow contract to receive funds
    receive() external payable {}

    // call withdrawAll on target C as this contract
    function callWithdraw(address target, address payable recipient, address /*unused*/) public {
        C(target).withdrawAll(recipient);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: actorIsDeployer (bool): if true call as this contract (deployer/owner),
    // recipient: where funds should be sent, fund: amount to fund c before withdrawal
    function run(bool actorIsDeployer, address payable recipient, uint256 fund) public payable {
        // ensure we can fund c
        require(address(this).balance >= fund);

        // Fund contract c by sending Ether to it via low-level call to trigger fallback
        (bool sent, ) = address(c).call{value: fund}("");
        require(sent);

        // Observe balances and owner
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        address owner = c.owner();

        bool reverted;

        if (actorIsDeployer) {
            // This contract deployed c, so msg.sender == this -> caller equals owner if owner == address(this)
            // Call directly and catch revert
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Call from another contract (forwarder) so msg.sender != address(this)
            // Deploy a minimal forwarder that will call withdrawAll from its own address
            Forwarder f = new Forwarder{value: 0}();
            try f.callWithdraw{value:0}(address(c), recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If the caller used (actorIsDeployer == true) and owner == address(this), then call must succeed (not revert)
        // and all ETH moved from C to recipient (C balance becomes zero and recipient increases by beforeC).
        // Otherwise (caller is not owner) the call must revert and balances remain unchanged.
        assert(
            // case: this contract is owner and it was the caller
            (actorIsDeployer && owner == address(this) && !reverted && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            ||
            // case: either caller was not the deployer or deployer is not owner -> treated as non-owner calling
            ((!actorIsDeployer || owner != address(this)) && reverted && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    receive() external payable {}
}

